// Numeric equivalence to original MIT JS generated by math_reference.mjs.
#include "beauty_core.h"
#include <cassert>
#include <chrono>
#include <cmath>
#include <fstream>
#include <iostream>
#include <string>
using namespace trueitem;
static void near(float a,float b,const char *what,float tolerance=2e-6f){if(std::abs(a-b)>tolerance){std::cerr<<what<<": "<<a<<" != "<<b<<"\n";std::abort();}}
int main(int argc,char **argv){
    std::ifstream in(argc>1?argv[1]:"tests/math_reference.txt");assert(in);
    int count,cases;in>>count>>cases;assert(count==landmark_count);LandmarkFrame frame;frame.valid=true;frame.presence=1;
    for(auto &point:frame.points)in>>point.x>>point.y;
    int tested=0;
    for(int n=0;n<cases;++n){
        std::string name;std::uint32_t w,h;in>>name>>w>>h;BeautyParams p;
        int *controls[]={&p.smooth,&p.texture,&p.even,&p.radius,&p.sharpen,&p.slim,&p.chin,&p.eyes,&p.nose,&p.lips,&p.eyeBright,&p.underEye,&p.lipAmount,&p.blushAmount,&p.bright,&p.warmth,&p.vibrance,&p.contrast,&p.glow,&p.vignette,&p.grain};
        for(auto v:controls)in>>*v;for(auto &v:p.lip_rgb)in>>v;for(auto &v:p.blush_rgb)in>>v;in>>p.mirror;
        p.natural=false; // The JS fixture explicitly verifies the legacy renderer.
        int expected_count;float expected_blur;in>>expected_count>>expected_blur;
        Vec4 expected_blobs[4];for(auto &v:expected_blobs)for(float &x:v)in>>x;
        auto u=compute_uniforms(frame,p,w,h);assert(u.warp_count==expected_count);near(u.blur_scale,expected_blur,"blur");
        Vec4 actual_blobs[]={u.eye_l,u.eye_r,u.cheek_l,u.cheek_r};for(int i=0;i<4;++i)for(int j=0;j<4;++j)near(actual_blobs[i][j],expected_blobs[i][j],"blob");
        for(int i=0;i<expected_count;++i){Vec4 a,b;for(float &x:a)in>>x;for(float &x:b)in>>x;for(int j=0;j<4;++j){near(u.warp_p[i][j],a[j],"warp P");near(u.warp_q[i][j],b[j],"warp Q");}
            if(u.warp_p[i][3]<.5f)assert(std::hypot(u.warp_q[i][0],u.warp_q[i][1])<=u.warp_p[i][2]*.450001f);
        }
        if(name=="off"){assert(u.warp_count==0);for(Vec2 uv: {Vec2{0,0},Vec2{.37f,.63f},Vec2{1,1}}){auto mapped=apply_warp(uv,u);near(mapped[0],uv[0],"neutral x");near(mapped[1],uv[1],"neutral y");}near(u.shader.smooth,0,"off smoothing");near(u.shader.texture,1,"off texture");near(u.shader.bright,0,"off brightness");}
        if(name=="user"){near(u.shader.smooth,1,"user smooth");near(u.shader.texture,.26f,"user texture");near(u.shader.sharpen,.042f,"user sharpen");near(u.shader.radius,.665f,"user radius");near(u.shader.bright,.063f,"user bright");near(u.shader.warmth,.71f,"user warmth");near(u.shader.vibrance,.6f,"user vibrance");near(u.shader.contrast,.04f,"user contrast");near(u.shader.glow,.45f,"user glow");near(u.shader.vignette,.12f,"user vignette");assert(u.mirror);}
        ++tested;
    }
    assert(in.good());
    auto begin=std::chrono::steady_clock::now();auto mask=build_mask(frame,16.f/9);auto elapsed=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-begin).count();
    assert(mask.width==320&&mask.height==180&&mask.rgba.size()==320*180*4);
    auto pixel=[&](float x,float y,int channel){return mask.rgba[(int(y*mask.height)*mask.width+int(x*mask.width))*4+channel];};
    assert(pixel(.5f,.3f,0)>100);assert(pixel(.585f,.44f,2)>100);assert(pixel(.585f,.44f,0)<100);assert(pixel(.5f,.655f,1)>100);
    LandmarkFrame missing;auto blank=build_mask(missing,16.f/9);for(std::size_t i=0;i<blank.rgba.size();i+=4){assert(!blank.rgba[i]&&!blank.rgba[i+1]&&!blank.rgba[i+2]);assert(blank.rgba[i+3]==255);}
    auto fallback=compute_uniforms(missing,BeautyParams{},1280,720);assert(fallback.face==0&&fallback.warp_count==0);
    std::cout<<"PASS "<<tested<<" JS reference cases, 478 points, neutral identity, actual user preset, mask region/exclusion/fallback; mask "<<elapsed<<" ms\n";
}
